# G1a test-enabled browser-chrome packaging only.
# Restore an absent generated objdir JS staging Makefile using the upstream
# Makefile.in's real recipe. Do NOT disable stage-jstests, change the source
# template, or modify shared production build/packaging scripts.
$ErrorActionPreference = 'Stop'
if (-not $env:OBJDIR) { throw 'OBJDIR required' }
$srcRoot = (Get-Location).Path.Replace('\','/')
$templatePath = Join-Path (Get-Location) 'js/src/tests/Makefile.in'
if (-not (Test-Path -LiteralPath $templatePath)) {
  throw "Missing actual JS stage template: $templatePath"
}
$jsObjDir = Join-Path $env:OBJDIR 'js/src/tests'
$generated = Join-Path $jsObjDir 'Makefile'
if (Test-Path -LiteralPath $generated) {
  Write-Host 'Normal generated JS tests staging Makefile exists; no repair needed'
  exit 0
}
$template = [IO.File]::ReadAllText($templatePath)
$include = 'include $(topsrcdir)/config/rules.mk'
if (-not $template.Contains($include) -or
    -not $template.Contains('stage-package:') -or
    -not $template.Contains('--make-manifests')) {
  throw 'Unexpected source JS Makefile.in; refuse altered staging recipe'
}
$objdir = (Resolve-Path -LiteralPath $env:OBJDIR).Path.Replace('\','/')
$srcdir = (Join-Path (Get-Location) 'js/src/tests').Replace('\','/')
$python = (Get-Command python.exe -ErrorAction Stop).Source.Replace('\','/')
# Only provide the standard values normally generated by recursive make.
# Keep the original stage-package target and TEST_FILES inventory unchanged.
$prefix = @'
topsrcdir := __TOPSRC__
srcdir := __SRCDIR__
DEPTH := __OBJDIR__
DIST := $(DEPTH)/dist
PKG_STAGE := $(DIST)/test-stage
PYTHON3 := __PYTHON__
NSINSTALL := $(PYTHON3) $(topsrcdir)/config/nsinstall.py
TAR_CREATE_FLAGS := -cf
NULL :=
'@
$prefix = $prefix.Replace('__TOPSRC__',$srcRoot).Replace('__SRCDIR__',$srcdir).Replace('__OBJDIR__',$objdir).Replace('__PYTHON__',$python)
$recipe = $template.Replace($include,'')
New-Item -ItemType Directory -Force -Path $jsObjDir,'diagnostics' | Out-Null
[IO.File]::WriteAllText($generated, $prefix + [Environment]::NewLine + $recipe, (New-Object Text.UTF8Encoding($false)))
@(
  "source_under_test=$env:GITHUB_SHA",
  'purpose=materialize-missing-js-tests-objdir-Makefile',
  'source_recipe=js/src/tests/Makefile.in (unchanged)',
  "recipe_sha256=$((Get-FileHash -Algorithm SHA256 -LiteralPath $templatePath).Hash.ToLowerInvariant())",
  'js_tests_stage=real-stage-package-not-skipped',
  'scope=G1a-only-disposable-object-directory',
  "generated_path=$generated"
) | Set-Content -Encoding utf8 'diagnostics/g1a-js-stage-makefile-repair.txt'
Write-Host 'G1a: JS tests staging Makefile materialized from real source recipe; no JS test category removed'
